// Monta o pedido para o Claude a partir dos dados do Supabase
const d = $input.first().json;
const cfg = $('Configurações').first().json;

const counts = {
  alertas: d.planning_alerts.length,
  atrasados: d.late_deliverables.length,
  vencendo: d.deliverables_due_7_days.length,
  eventos: d.events_next_7_days.length,
  contratos: d.contracts_ending_90_days.length,
};

const system = [
  'Você é assistente do time de marketing esportivo de uma marca patrocinadora.',
  'Escreva o resumo semanal das parcerias esportivas em português do Brasil, para ser lido em 1 minuto.',
  'Regras:',
  '- Use SOMENTE os dados do JSON. Não invente eventos, datas, nomes ou números.',
  '- Responda apenas com um fragmento HTML usando as tags <h3>, <p>, <ul>, <li> e <strong>. Sem <html>, <body>, estilos ou markdown.',
  '- Seções, nesta ordem: "Prioridades da semana", "Agenda dos próximos 7 dias", "Entregáveis que vencem em breve", "Contratos a renovar".',
  '- Em "Prioridades da semana", liste primeiro entregáveis atrasados e ativações que ainda não saíram do planejamento a menos de ' + cfg.planning_lead_days + ' dias, com o responsável quando houver.',
  '- Datas no formato dd/mm (ex.: 05/11). Diga também "hoje", "amanhã" ou "em N dias" quando ajudar.',
  '- Se uma seção não tiver itens, escreva uma frase curta dizendo que está tudo em dia.',
  '- Feche com uma frase de próximo passo objetiva.',
].join('\n');

return [{
  json: {
    counts,
    digest: d,
    body: {
      model: cfg.anthropic_model,
      max_tokens: 1500,
      system,
      messages: [{ role: 'user', content: 'Dados da semana (JSON):\n' + JSON.stringify(d) }],
    },
  },
}];

// Monta o e-mail com o texto do Claude.
// Se a IA falhar, envia um resumo simples gerado direto dos dados (o time não fica sem o aviso).
const cfg = $('Configurações').first().json;
const { digest: d, counts } = $('Montar pedido para o Claude').first().json;
const res = $input.first().json;

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const br = (iso) => iso ? iso.slice(8, 10) + '/' + iso.slice(5, 7) : '';

// Mantém só as tags permitidas, sem atributos (o HTML vem de um modelo, então é limpo antes de enviar)
function sanitize(html) {
  return html
    .replace(/^\s*\x60\x60\x60(?:html)?|\x60\x60\x60\s*$/g, '')
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
    .replace(/<\/?([a-z0-9]+)[^>]*>/gi, (tag, name) =>
      ['h3', 'p', 'ul', 'li', 'strong', 'em', 'br'].includes(name.toLowerCase())
        ? tag.replace(/^<(\/?)([a-z0-9]+)[^>]*>$/i, '<$1$2>') : '')
    .trim();
}

function fallback() {
  const list = (title, items, fmt) =>
    '<h3>' + title + '</h3>' + (items.length ? '<ul>' + items.map((i) => '<li>' + fmt(i) + '</li>').join('') + '</ul>' : '<p>Tudo em dia.</p>');
  return [
    list('Entregáveis atrasados', d.late_deliverables, (i) => '<strong>' + esc(i.title) + '</strong> · ' + esc(i.team) + ' · atrasado há ' + i.days_late + ' dia(s)'),
    list('Ativações para planejar', d.planning_alerts, (i) => '<strong>' + esc(i.title) + '</strong> · ' + esc(i.team) + ' · ' + br(i.date) + ' (em ' + i.days_left + ' dias)' + (i.owner ? ' · ' + esc(i.owner) : '')),
    list('Agenda dos próximos 7 dias', d.events_next_7_days, (i) => br(i.date) + (i.time ? ' ' + i.time : '') + ' · <strong>' + esc(i.title) + '</strong> · ' + esc(i.team)),
    list('Entregáveis que vencem em breve', d.deliverables_due_7_days, (i) => '<strong>' + esc(i.title) + '</strong> · ' + esc(i.team) + ' · ' + br(i.due)),
    list('Contratos a renovar', d.contracts_ending_90_days, (i) => esc(i.team) + ' · termina em ' + br(i.contract_end) + ' (' + i.days_left + ' dias)'),
  ].join('');
}

const aiText = (res.content || []).find((c) => c.type === 'text')?.text;
const usedAI = !!aiText;
const body = usedAI ? sanitize(aiText) : fallback();

const chip = (n, label, color) =>
  '<td style="padding:4px 12px 4px 0"><span style="font:600 20px Arial;color:' + color + '">' + n + '</span><br><span style="font:12px Arial;color:#64748b">' + label + '</span></td>';

const html = '<div style="max-width:620px;margin:0 auto;font:15px/1.5 Arial,sans-serif;color:#17202a">'
  + '<h2 style="margin:0 0 4px">⚽ Resumo semanal das parcerias</h2>'
  + '<p style="margin:0 0 16px;color:#64748b">Semana de ' + br(d.generated_on) + '</p>'
  + '<table role="presentation" style="margin-bottom:16px"><tr>'
  + chip(counts.atrasados, 'atrasados', '#dc2626')
  + chip(counts.alertas, 'ativações p/ planejar', '#d97706')
  + chip(counts.eventos, 'eventos em 7 dias', '#1d4ed8')
  + chip(counts.vencendo, 'vencendo', '#0f766e')
  + '</tr></table>'
  + body
  + (cfg.app_url ? '<p style="margin-top:24px"><a href="' + esc(cfg.app_url) + '" style="background:#1d4ed8;color:#fff;padding:10px 16px;border-radius:8px;text-decoration:none">Abrir o app</a></p>' : '')
  + '<p style="margin-top:24px;font-size:12px;color:#94a3b8">Gerado automaticamente pelo n8n com dados do Supabase'
  + (usedAI ? ' e texto do Claude.' : '. A IA estava indisponível, então este é o resumo simples.') + '</p>'
  + '</div>';

const urgent = counts.atrasados + counts.alertas;
return [{
  json: {
    subject: 'Parcerias esportivas · semana de ' + br(d.generated_on) + (urgent ? ' · ' + urgent + ' ponto(s) de atenção' : ' · tudo em dia'),
    html,
    used_ai: usedAI,
  },
}];
